int linearSearch(List<int> items, int target) {
  for (var i = 0; i < items.length; i++) {
    if (items[i] == target) {
      return i;
    }
  }
  return -1;
}

int binarySearch(List<int> sorted, int target) {
  var low = 0;
  var high = sorted.length - 1;
  while (low <= high) {
    final mid = low + (high - low) ~/ 2;
    if (sorted[mid] == target) {
      return mid;
    }
    if (sorted[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return -1;
}

List<int> bubbleSort(List<int> input) {
  final result = [...input];
  for (var pass = 0; pass < result.length - 1; pass++) {
    for (var i = 0; i < result.length - 1 - pass; i++) {
      if (result[i] > result[i + 1]) {
        final temp = result[i];
        result[i] = result[i + 1];
        result[i + 1] = temp;
      }
    }
  }
  return result;
}

List<int> selectionSort(List<int> input) {
  final result = [...input];
  for (var i = 0; i < result.length - 1; i++) {
    var minIndex = i;
    for (var j = i + 1; j < result.length; j++) {
      if (result[j] < result[minIndex]) {
        minIndex = j;
      }
    }
    final temp = result[i];
    result[i] = result[minIndex];
    result[minIndex] = temp;
  }
  return result;
}

List<int> insertionSort(List<int> input) {
  final result = [...input];
  for (var i = 1; i < result.length; i++) {
    final key = result[i];
    var j = i - 1;
    while (j >= 0 && result[j] > key) {
      result[j + 1] = result[j];
      j--;
    }
    result[j + 1] = key;
  }
  return result;
}

List<int> mergeSort(List<int> input) {
  final result = [...input];
  _sortRange(result, 0, result.length - 1);
  return result;
}

void _sortRange(List<int> values, int left, int right) {
  if (left >= right) {
    return;
  }
  final mid = left + (right - left) ~/ 2;
  _sortRange(values, left, mid);
  _sortRange(values, mid + 1, right);
  _merge(values, left, mid, right);
}

void _merge(List<int> values, int left, int mid, int right) {
  final leftHalf = values.sublist(left, mid + 1);
  final rightHalf = values.sublist(mid + 1, right + 1);
  var i = 0;
  var j = 0;
  var k = left;
  while (i < leftHalf.length && j < rightHalf.length) {
    if (leftHalf[i] <= rightHalf[j]) {
      values[k++] = leftHalf[i++];
    } else {
      values[k++] = rightHalf[j++];
    }
  }
  while (i < leftHalf.length) {
    values[k++] = leftHalf[i++];
  }
  while (j < rightHalf.length) {
    values[k++] = rightHalf[j++];
  }
}

List<int> quickSort(List<int> input) {
  final result = [...input];
  _quickSortRange(result, 0, result.length - 1);
  return result;
}

void _quickSortRange(List<int> values, int low, int high) {
  if (low >= high) {
    return;
  }
  final pivotIndex = _partition(values, low, high);
  _quickSortRange(values, low, pivotIndex - 1);
  _quickSortRange(values, pivotIndex + 1, high);
}

int _partition(List<int> values, int low, int high) {
  final pivot = values[high];
  var boundary = low - 1;
  for (var j = low; j < high; j++) {
    if (values[j] <= pivot) {
      boundary++;
      final temp = values[boundary];
      values[boundary] = values[j];
      values[j] = temp;
    }
  }
  final temp = values[boundary + 1];
  values[boundary + 1] = values[high];
  values[high] = temp;
  return boundary + 1;
}

List<int> heapSort(List<int> input) {
  final result = [...input];
  for (var i = result.length ~/ 2 - 1; i >= 0; i--) {
    _siftDown(result, result.length, i);
  }
  for (var end = result.length - 1; end > 0; end--) {
    final temp = result[0];
    result[0] = result[end];
    result[end] = temp;
    _siftDown(result, end, 0);
  }
  return result;
}

void _siftDown(List<int> values, int size, int root) {
  while (true) {
    var largest = root;
    final left = 2 * root + 1;
    final right = 2 * root + 2;
    if (left < size && values[left] > values[largest]) {
      largest = left;
    }
    if (right < size && values[right] > values[largest]) {
      largest = right;
    }
    if (largest == root) {
      return;
    }
    final temp = values[root];
    values[root] = values[largest];
    values[largest] = temp;
    root = largest;
  }
}

Map<String, List<String>> buildGraph(List<(String, String)> edges) {
  final graph = <String, List<String>>{};
  for (final (from, to) in edges) {
    graph.putIfAbsent(from, () => <String>[]).add(to);
    graph.putIfAbsent(to, () => <String>[]).add(from);
  }
  return graph;
}

List<String> bfs(Map<String, List<String>> graph, String start) {
  final visited = <String>{start};
  final order = <String>[start];
  final queue = <String>[start];
  var head = 0;
  while (head < queue.length) {
    final node = queue[head++];
    for (final next in graph[node] ?? const <String>[]) {
      if (visited.add(next)) {
        queue.add(next);
        order.add(next);
      }
    }
  }
  return order;
}

List<String> dfs(Map<String, List<String>> graph, String start) {
  final visited = <String>{};
  final order = <String>[];
  void visit(String node) {
    if (!visited.add(node)) {
      return;
    }
    order.add(node);
    for (final next in graph[node] ?? const <String>[]) {
      visit(next);
    }
  }

  visit(start);
  return order;
}

Map<String, int> dijkstra(Map<String, Map<String, int>> graph, String start) {
  final distances = <String, int>{start: 0};
  final visited = <String>{};
  while (true) {
    String? current;
    var best = 0;
    for (final entry in distances.entries) {
      if (visited.contains(entry.key)) {
        continue;
      }
      if (current == null || entry.value < best) {
        current = entry.key;
        best = entry.value;
      }
    }
    if (current == null) {
      return distances;
    }
    visited.add(current);
    final edges = graph[current] ?? const <String, int>{};
    for (final edge in edges.entries) {
      final candidate = best + edge.value;
      final known = distances[edge.key];
      if (known == null || candidate < known) {
        distances[edge.key] = candidate;
      }
    }
  }
}
